/* eslint-disable @typescript-eslint/no-unused-expressions */

import CompactAdjacencyMatrix = require( './index' );

/**
* Callback function.
*
* @param value - list element
* @param i - list element index
* @returns list of vertices
*/
function clbk( value: unknown, i: number ): ArrayLike<number> {
	return [ i, value as number ];
}


// TESTS //

// The function returns an adjacency matrix...
{
	CompactAdjacencyMatrix( 4 ); // $ExpectType CompactAdjacencyMatrix
	new CompactAdjacencyMatrix( 4 ); // $ExpectType CompactAdjacencyMatrix
}

// The function creates an adjacency matrix from an adjacency list...
{
	const list = [ [ 1, 2 ], [ 2 ], [ 3 ], [] ];

	CompactAdjacencyMatrix.fromAdjacencyList( list ); // $ExpectType CompactAdjacencyMatrix
	CompactAdjacencyMatrix.fromAdjacencyList( list, clbk ); // $ExpectType CompactAdjacencyMatrix
	CompactAdjacencyMatrix.fromAdjacencyList( list, clbk, {} ); // $ExpectType CompactAdjacencyMatrix
}

// The function creates an adjacency matrix from a list of edges...
{
	const edges = [ [ 0, 1 ], [ 0, 2 ], [ 1, 2 ], [ 2, 3 ] ];

	CompactAdjacencyMatrix.fromEdges( 4, edges ); // $ExpectType CompactAdjacencyMatrix
	CompactAdjacencyMatrix.fromEdges( 4, edges, clbk ); // $ExpectType CompactAdjacencyMatrix
	CompactAdjacencyMatrix.fromEdges( 4, edges, clbk, {} ); // $ExpectType CompactAdjacencyMatrix
}

// The function returns an adjacency matrix with methods for inspecting and mutating the graph...
{
	const adj = new CompactAdjacencyMatrix( 4 );

	adj.addEdge( 0, 1 ); // $ExpectType CompactAdjacencyMatrix
	adj.hasEdge( 0, 1 ); // $ExpectType boolean
	adj.inDegree( 1 ); // $ExpectType number
	adj.inEdges( 1 ); // $ExpectType number[]
	adj.outDegree( 0 ); // $ExpectType number
	adj.outEdges( 0 ); // $ExpectType number[]
	adj.removeEdge( 0, 1 ); // $ExpectType CompactAdjacencyMatrix
	adj.toAdjacencyList(); // $ExpectType number[][]
	adj.edges; // $ExpectType number[][]
	adj.nedges; // $ExpectType number
	adj.nvertices; // $ExpectType number

	const results = adj.toposort();

	results[ 0 ]; // $ExpectType number[] | null
	results[ 1 ]; // $ExpectType number[] | null
}

// The compiler throws an error if the constructor is provided a first argument which is not a number...
{
	CompactAdjacencyMatrix( '4' ); // $ExpectError
	CompactAdjacencyMatrix( true ); // $ExpectError
	CompactAdjacencyMatrix( false ); // $ExpectError
	CompactAdjacencyMatrix( null ); // $ExpectError
	CompactAdjacencyMatrix( void 0 ); // $ExpectError
	CompactAdjacencyMatrix( {} ); // $ExpectError
	CompactAdjacencyMatrix( ( x: number ): number => x ); // $ExpectError

	new CompactAdjacencyMatrix( '4' ); // $ExpectError
	new CompactAdjacencyMatrix( true ); // $ExpectError
	new CompactAdjacencyMatrix( false ); // $ExpectError
	new CompactAdjacencyMatrix( null ); // $ExpectError
	new CompactAdjacencyMatrix( void 0 ); // $ExpectError
	new CompactAdjacencyMatrix( {} ); // $ExpectError
	new CompactAdjacencyMatrix( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	CompactAdjacencyMatrix(); // $ExpectError
	CompactAdjacencyMatrix( 4, 5 ); // $ExpectError

	new CompactAdjacencyMatrix(); // $ExpectError
	new CompactAdjacencyMatrix( 4, 5 ); // $ExpectError
}

// The compiler throws an error if the function is provided a first argument to `fromAdjacencyList` which is not an array-like object or iterable...
{
	CompactAdjacencyMatrix.fromAdjacencyList( 123 ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( true ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( false ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( null ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( void 0 ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( {} ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a callback argument to `fromAdjacencyList` which is not a function...
{
	CompactAdjacencyMatrix.fromAdjacencyList( [], 123 ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( [], 'abc' ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( [], true ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( [], null ); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( [], {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments to `fromAdjacencyList`...
{
	CompactAdjacencyMatrix.fromAdjacencyList(); // $ExpectError
	CompactAdjacencyMatrix.fromAdjacencyList( [], clbk, {}, 5 ); // $ExpectError
}

// The compiler throws an error if the function is provided a first argument to `fromEdges` which is not a number...
{
	CompactAdjacencyMatrix.fromEdges( '4', [] ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( true, [] ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( false, [] ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( null, [] ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( void 0, [] ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( {}, [] ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( ( x: number ): number => x, [] ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument to `fromEdges` which is not an array-like object or iterable...
{
	CompactAdjacencyMatrix.fromEdges( 4, 123 ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, true ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, false ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, null ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, void 0 ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, {} ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a callback argument to `fromEdges` which is not a function...
{
	CompactAdjacencyMatrix.fromEdges( 4, [], 123 ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, [], 'abc' ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, [], true ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, [], null ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, [], {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments to `fromEdges`...
{
	CompactAdjacencyMatrix.fromEdges(); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4 ); // $ExpectError
	CompactAdjacencyMatrix.fromEdges( 4, [], clbk, {}, 5 ); // $ExpectError
}

// The compiler throws an error if a method is provided an argument which is not a number...
{
	const adj = new CompactAdjacencyMatrix( 4 );

	adj.addEdge( '0', 1 ); // $ExpectError
	adj.addEdge( 0, true ); // $ExpectError
	adj.hasEdge( null, 1 ); // $ExpectError
	adj.hasEdge( 0, void 0 ); // $ExpectError
	adj.inDegree( {} ); // $ExpectError
	adj.inEdges( [] ); // $ExpectError
	adj.outDegree( ( x: number ): number => x ); // $ExpectError
	adj.outEdges( false ); // $ExpectError
	adj.removeEdge( 0, null ); // $ExpectError
}

// The compiler throws an error if a method is provided an unsupported number of arguments...
{
	const adj = new CompactAdjacencyMatrix( 4 );

	adj.addEdge( 0 ); // $ExpectError
	adj.addEdge( 0, 1, 2 ); // $ExpectError
	adj.hasEdge( 0 ); // $ExpectError
	adj.inDegree(); // $ExpectError
	adj.inEdges(); // $ExpectError
	adj.outDegree(); // $ExpectError
	adj.outEdges(); // $ExpectError
	adj.removeEdge( 0 ); // $ExpectError
	adj.toAdjacencyList( 1 ); // $ExpectError
	adj.toposort( 1 ); // $ExpectError
}

// The compiler throws an error if attempting to assign to a read-only property...
{
	const adj = new CompactAdjacencyMatrix( 4 );

	adj.edges = []; // $ExpectError
	adj.nedges = 5; // $ExpectError
	adj.nvertices = 5; // $ExpectError
}
